CREATE TABLE benchmarks (
	id TEXT PRIMARY KEY NOT NULL, 
	created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, 
	updated TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, 
	name TEXT NOT NULL, 
	category TEXT NOT NULL, 
	workoutDescription TEXT NOT NULL, 
	scoringType TEXT NOT NULL, 
	intensity INTEGER, 
	movementTags TEXT, 
	equipment TEXT, 
	timeDomain TEXT, 
	coachNotes TEXT, 
	status TEXT DEFAULT "draft", 
	sortOrder INTEGER DEFAULT 0
);
CREATE INDEX idx_benchmarks_status ON benchmarks (status COLLATE NOCASE);
CREATE INDEX idx_benchmarks_category ON benchmarks (category COLLATE NOCASE);
CREATE TRIGGER tgr_benchmarks_raise_on_created_update BEFORE UPDATE OF created ON benchmarks BEGIN SELECT RAISE(FAIL, 'Cannot update created column') WHERE OLD.created != NEW.created; END;